private val Scheme = darkColorScheme(primary=Color(0xFF70D8C8),onPrimary=Color(0xFF06332E),primaryContainer=Color(0xFF32A192),onPrimaryContainer=Color.White,secondary=Color(0xFF4EDEA3),background=Color(0xFF202020),surface=Color(0xFF292929),surfaceVariant=Color(0xFF383838),onSurface=Color(0xFFF4F7F5),onSurfaceVariant=Color(0xFFD7E0DC),outline=Color(0xFFAAB7B3),error=Color(0xFFFFB4AB))
