private enum class Page{HOME,KASIR,TRANSAKSI,LAPORAN,STOK,KATEGORI,SERVICE,KASBON,PELANGGAN,PENGELUARAN,GAJI,LAINNYA,PENGATURAN}
private fun JSONObject.s(vararg k:String)=k.firstNotNullOfOrNull{optString(it).takeIf{v->v.isNotBlank()}}?:"-"
private fun JSONObject.n(vararg k:String)=k.firstNotNullOfOrNull{optString(it).replace(",","").toDoubleOrNull()?.toLong()}?:0L
private fun JSONObject.a(vararg k:String)=k.firstNotNullOfOrNull{optJSONArray(it)}?.let{a->(0 until a.length()).mapNotNull(a::optJSONObject)}?:emptyList()
private fun rp(n:Long)="Rp ${Money.format(n)}"

class NativeActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{MaterialTheme(colorScheme=Scheme){LoginGate()}}}}

@Composable private fun LoginGate(){val c=LocalContext.current;val api=remember(c){ApiClient(c)};val scope=rememberCoroutineScope();var ready by remember{mutableStateOf(false)};var error by remember{mutableStateOf("")};fun login()=scope.launch{error="";runCatching{if(api.hasToken())runCatching{api.me()}.getOrElse{api.login("demo","demodemo")}else api.login("demo","demodemo")}.onSuccess{ready=true}.onFailure{error=it.message?:"Login gagal"}};LaunchedEffect(Unit){login()};if(ready)App(api)else Box(Modifier.fillMaxSize().background(Scheme.background),contentAlignment=Alignment.Center){Column(horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.spacedBy(12.dp)){Text("Irkop Cell",style=MaterialTheme.typography.headlineLarge,fontWeight=FontWeight.Bold);if(error.isBlank())CircularProgressIndicator()else Button(onClick={login()}){Text("Coba Lagi")};Text(if(error.isBlank())"Menyiapkan sesi kasir…" else error,color=if(error.isBlank())Muted else Scheme.error)}}}

@Composable private fun App(api:ApiClient){var page by remember{mutableStateOf(Page.HOME)};var history by remember{mutableStateOf(emptyList<Page>())};var sheet by remember{mutableStateOf(false)};val role=remember{api.cachedUser()?.optString("role").orEmpty().uppercase()};fun allowed(p:Page)=p!=Page.GAJI||role !in setOf("KARYAWAN","KASIR","CASHIER");fun open(p:Page){if(allowed(p)&&p!=page){history=history+p;page=p}};fun root(p:Page){if(allowed(p)){page=p;history=emptyList()}};fun back(){if(history.isNotEmpty()){page=history.last();history=history.dropLast(1)}else if(page!=Page.HOME)page=Page.HOME};BackHandler{back()};Scaffold(containerColor=Scheme.background,bottomBar={NavigationBar(containerColor=Color(0xFF292929)){NavigationBarItem(selected=page==Page.HOME,onClick={root(Page.HOME)},icon={Icon(Icons.Default.Home,"Beranda")},label={Text("Beranda")});NavigationBarItem(selected=page==Page.KASIR,onClick={root(Page.KASIR)},icon={Icon(Icons.Default.PointOfSale,"Kasir")},label={Text("Kasir")});NavigationBarItem(selected=page==Page.LAPORAN,onClick={root(Page.LAPORAN)},icon={Icon(Icons.Default.Assessment,"Laporan")},label={Text("Laporan")});NavigationBarItem(selected=page==Page.LAINNYA,onClick={root(Page.LAINNYA)},icon={Icon(Icons.Default.MoreHoriz,"Lainnya")},label={Text("Lainnya")})}},floatingActionButton={FloatingActionButton(onClick={sheet=true},containerColor=Scheme.primary,contentColor=Scheme.onPrimary){Icon(Icons.Default.Add,"Transaksi Baru")}}){p->when(page){Page.HOME->Home(p,::open,role);Page.KASIR->Cashier(p,api,::back);Page.TRANSAKSI->Transactions(p,api,::back);Page.LAPORAN->Reports(p,api,::back);Page.KASBON->Kasbon(p,api,::back);Page.GAJI->Payroll(p,api,::back);Page.LAINNYA->More(p,::open,::back,allowed(Page.GAJI));Page.STOK->Unsupported(p,"Stok","Endpoint produk/stok belum ada di kontrak API resmi.",::back);Page.KATEGORI->Unsupported(p,"Kategori","Endpoint kategori belum ada di kontrak API resmi.",::back);Page.SERVICE->Unsupported(p,"Service HP","Endpoint service belum ada di kontrak API resmi.",::back);Page.PELANGGAN->Unsupported(p,"Pelanggan","Endpoint pelanggan belum ada di kontrak API resmi.",::back);Page.PENGELUARAN->Unsupported(p,"Pengeluaran","Endpoint pengeluaran belum ada di kontrak API resmi.",::back);Page.PENGATURAN->Unsupported(p,"Pengaturan","Endpoint pengaturan belum ada di kontrak API resmi.",::back)}};if(sheet)TransactionSheet(api){sheet=false}}

@Composable private fun Header(title:String,sub:String?=null,back:(()->Unit)?=null){Row(Modifier.fillMaxWidth().padding(vertical=8.dp),verticalAlignment=Alignment.CenterVertically){if(back!=null)IconButton(onClick=back){Icon(Icons.Default.ArrowBack,"Kembali")};Column(Modifier.weight(1f)){Text(title,style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);if(!sub.isNullOrBlank())Text(sub,color=Muted)}}}
