@Composable private fun Home(p:PaddingValues,open:(Page)->Unit,role:String){LazyColumn(Modifier.fillMaxSize().padding(p),contentPadding=PaddingValues(16.dp,8.dp,16.dp,110.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("Irkop Cell",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("Sesi Kasir: Aktif",color=Good,fontWeight=FontWeight.Bold)};Text(role.ifBlank{"KASIR"},color=Scheme.primary,fontWeight=FontWeight.Bold)}};item{CardText("Sesi Kasir","Opening, saldo akun dan rekonsiliasi"){open(Page.KASIR)}};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Metric("Saldo Kas","—",Modifier.weight(1f));Metric("Omzet Hari Ini","—",Modifier.weight(1f));Metric("Transaksi","—",Modifier.weight(1f))}};item{Text("Menu Kasir Utama",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Quick("Stok",Icons.Default.Inventory2,Modifier.weight(1f)){open(Page.STOK)};Quick("Kasbon",Icons.Default.ReceiptLong,Modifier.weight(1f)){open(Page.KASBON)};Quick("Pelanggan",Icons.Default.People,Modifier.weight(1f)){open(Page.PELANGGAN)};Quick("Pengeluaran",Icons.Default.Wallet,Modifier.weight(1f)){open(Page.PENGELUARAN)}}};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Quick("Service",Icons.Default.Build,Modifier.weight(1f)){open(Page.SERVICE)};Quick("Gaji",Icons.Default.Assessment,Modifier.weight(1f)){open(Page.GAJI)};Quick("Laporan",Icons.Default.Assessment,Modifier.weight(1f)){open(Page.LAPORAN)};Quick("Transaksi",Icons.Default.ReceiptLong,Modifier.weight(1f)){open(Page.TRANSAKSI)}}};item{CardText("Backend","Endpoint resmi dipakai untuk data finansial. Modul tanpa kontrak tidak mengirim request fiktif.")}}}

@Composable private fun Cashier(p:PaddingValues,api:ApiClient,back:()->Unit){var data by remember{mutableStateOf<JSONObject?>(null)};var error by remember{mutableStateOf("")};var opening by remember{mutableStateOf(false)};var closing by remember{mutableStateOf(false)};val scope=rememberCoroutineScope();fun load()=scope.launch{runCatching{api.kasirCurrent()}.onSuccess{data=it;error=""}.onFailure{error=it.message?:"Gagal memuat"}};LaunchedEffect(Unit){load()};val accounts=data?.a("saldo","saldo_akun","accounts","akun").orEmpty();LazyColumn(Modifier.fillMaxSize().padding(p),contentPadding=PaddingValues(16.dp,8.dp,16.dp,110.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Header("Kasir & Rekonsiliasi","GET /api/kasir/current",back)};item{CardText("Status Sesi",data?.s("status","state")?.uppercase()?:"MEMUAT")};if(error.isNotBlank())item{CardText("Error",error)};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(Modifier.weight(1f),onClick={opening=true}){Text("Opening")};OutlinedButton(Modifier.weight(1f),onClick={closing=true}){Text("Closing")}}};item{Text("Saldo Akun",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)};if(accounts.isEmpty())item{CardText("Saldo","Belum ada rincian saldo dari server.")};items(accounts){a->Row(Modifier.fillMaxWidth().padding(5.dp),verticalAlignment=Alignment.CenterVertically){Text(a.s("nama_akun","nama","akun"),Modifier.weight(1f));Text(rp(a.n("saldo","saldo_real","nominal")),fontWeight=FontWeight.Bold)}}};if(opening)AccountDialog("Opening Kasir",api,false){opening=false;load()};if(closing)AccountDialog("Closing Kasir",api,true){closing=false;load()}}

@Composable private fun AccountDialog(title:String,api:ApiClient,closing:Boolean,done:()->Unit){var fields by remember{mutableStateOf(listOf("Kas" to "","OrderKuota" to "","DANA" to "","SeaBank" to "","QRIS" to ""))};var note by remember{mutableStateOf("")};var error by remember{mutableStateOf("")};val scope=rememberCoroutineScope();AlertDialog(onDismissRequest=done,title={Text(title)},text={Column(Modifier.verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(7.dp)){fields.forEachIndexed{i,pair->OutlinedTextField(pair.second,{v->fields=fields.toMutableList().also{it[i]=pair.first to v}},label={Text(pair.first)},singleLine=true,modifier=Modifier.fillMaxWidth())};if(closing)OutlinedTextField(note,{note=it},label={Text("Catatan closing")},modifier=Modifier.fillMaxWidth());if(error.isNotBlank())Text(error,color=Scheme.error)}},confirmButton={Button(onClick={scope.launch{val arr=JSONArray();fields.forEach{(name,value)->arr.put(JSONObject().put("nama_akun",name).put(if(closing)"saldo_real" else "saldo",value.toLongOrNull()?:0L))};runCatching{if(closing)api.kasirClosing(arr,note)else api.kasirOpening(arr)}.onSuccess{done()}.onFailure{error=it.message?:"Gagal menyimpan"}}}){Text("Simpan")}},dismissButton={TextButton(onClick=done){Text("Batal")}})}

@Composable private fun Transactions(p:PaddingValues,api:ApiClient,back:()->Unit){var rows by remember{mutableStateOf(emptyList<JSONObject>())};var date by remember{mutableStateOf("")};var error by remember{mutableStateOf("")};val scope=rememberCoroutineScope();fun load()=scope.launch{runCatching{api.transaksi(if(date.isBlank())emptyMap()else mapOf("date" to date,"limit" to "100"))}.onSuccess{rows=it.a("items","data","transaksi","results");error=""}.onFailure{error=it.message?:"Gagal memuat"}};LaunchedEffect(Unit){load()};LazyColumn(Modifier.fillMaxSize().padding(p),contentPadding=PaddingValues(16.dp,8.dp,16.dp,110.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Header("Transaksi","GET /api/transaksi",back)};item{OutlinedTextField(date,{date=it},label={Text("Tanggal YYYY-MM-DD")},singleLine=true,modifier=Modifier.fillMaxWidth(),trailingIcon={IconButton(onClick={load()}){Icon(Icons.Default.Refresh,"Muat")}})};if(error.isNotBlank())item{CardText("Error",error)};if(rows.isEmpty()&&error.isBlank())item{CardText("Belum ada data","Tidak ada transaksi pada filter ini.")};items(rows){t->TransactionCard(t,api){load()}}}}
@Composable private fun TransactionCard(t:JSONObject,api:ApiClient,changed:()->Unit){var confirm by remember{mutableStateOf(false)};val scope=rememberCoroutineScope();val id=t.s("id","transaksi_id");Card(colors=CardDefaults.cardColors(CardColor),shape=RoundedCornerShape(16.dp)){Row(Modifier.fillMaxWidth().padding(14.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(t.s("nomor","kode","invoice","id"),fontWeight=FontWeight.Bold);Text(t.s("metode_bayar","metode","payment_method"),color=Muted);Text(rp(t.n("total","nominal","grand_total")),color=Good,fontWeight=FontWeight.Bold)};IconButton(onClick={confirm=true}){Icon(Icons.Default.Delete,"Hapus")}}};if(confirm)AlertDialog(onDismissRequest={confirm=false},title={Text("Hapus transaksi?")},text={Text("Transaksi akan di-soft-delete dan mutasi dibalik oleh backend.")},confirmButton={Button(onClick={scope.launch{runCatching{api.deleteTransaksi(id,"Dihapus dari aplikasi")}.onSuccess{changed()}};confirm=false}){Text("Hapus")}},dismissButton={TextButton(onClick={confirm=false}){Text("Batal")}})}

@Composable private fun Reports(p:PaddingValues,api:ApiClient,back:()->Unit){var data by remember{mutableStateOf<JSONObject?>(null)};var error by remember{mutableStateOf("")};val scope=rememberCoroutineScope();val month=remember{java.time.LocalDate.now().toString().substring(0,7)};LaunchedEffect(Unit){scope.launch{runCatching{api.laporanBulan(month)}.onSuccess{data=it}.onFailure{error=it.message?:"Gagal memuat laporan"}}};LazyColumn(Modifier.fillMaxSize().padding(p),contentPadding=PaddingValues(16.dp,8.dp,16.dp,110.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Header("Laporan Kasir","GET /api/laporan/bulan • $month",back)};if(error.isNotBlank())item{CardText("Error",error)};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Metric("Omzet",rp(data?.n("omzet","total_omzet","penjualan")?:0L),Modifier.weight(1f));Metric("Transaksi",(data?.n("jumlah_transaksi","total_transaksi","count")?:0L).toString(),Modifier.weight(1f))}};item{CardText("Ringkasan","Data laporan ditampilkan dari response backend, bukan raw JSON.")}}}

@Composable private fun Kasbon(p:PaddingValues,api:ApiClient,back:()->Unit){var data by remember{mutableStateOf<JSONObject?>(null)};var error by remember{mutableStateOf("")};var add by remember{mutableStateOf(false)};val scope=rememberCoroutineScope();fun load()=scope.launch{runCatching{api.kasbon()}.onSuccess{data=it;error=""}.onFailure{error=it.message?:"Gagal memuat kasbon"}};LaunchedEffect(Unit){load()};val rows=data?.a("items","data","kasbon","results").orEmpty();LazyColumn(Modifier.fillMaxSize().padding(p),contentPadding=PaddingValues(16.dp,8.dp,16.dp,110.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Header("Kasbon Pelanggan","GET /api/kasbon",back)};item{Button(Modifier.fillMaxWidth(),onClick={add=true}){Text("Tambah Kasbon")}};if(error.isNotBlank())item{CardText("Error",error)};if(rows.isEmpty()&&error.isBlank())item{CardText("Belum ada kasbon","Server tidak mengembalikan data kasbon.")};items(rows){r->CardText(r.s("nama_pelanggan","pelanggan","nama"),"Sisa: ${rp(r.n("sisa","saldo","nominal"))} • Jatuh tempo: ${r.s("jatuh_tempo","tanggal_jatuh_tempo")}")}};if(add)SimpleJsonDialog("Tambah Kasbon","pelanggan_id","nominal"){body->scope.launch{runCatching{api.createKasbon(body)}.onSuccess{add=false;load()}.onFailure{error=it.message?:"Gagal menyimpan"}}}}

@Composable private fun Payroll(p:PaddingValues,api:ApiClient,back:()->Unit){var data by remember{mutableStateOf<JSONObject?>(null)};var rate by remember{mutableStateOf<JSONObject?>(null)};var error by remember{mutableStateOf("")};val scope=rememberCoroutineScope();LaunchedEffect(Unit){scope.launch{runCatching{api.gaji()}.onSuccess{data=it}.onFailure{error=it.message?:"Gagal memuat gaji"};runCatching{api.gajiRates()}.onSuccess{rate=it}}};LazyColumn(Modifier.fillMaxSize().padding(p),contentPadding=PaddingValues(16.dp,8.dp,16.dp,110.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Header("Gaji Karyawan","GET /api/gaji + /api/gaji/rate",back)};if(error.isNotBlank())item{CardText("Error",error)};item{CardText("Payroll","Data payroll diproses server. Response mentah tidak ditampilkan sebagai JSON.")};item{CardText("Jumlah data",(data?.a("items","data","results")?.size?:0).toString())};item{CardText("Rate",rate?.s("status","message")?:"Rate tersedia dari endpoint resmi.")}}}

