@Composable private fun TransactionSheet(api:ApiClient,close:()->Unit){var product by remember{mutableStateOf("")};var qty by remember{mutableStateOf("1")};var method by remember{mutableStateOf("Tunai")};var account by remember{mutableStateOf("")};var customer by remember{mutableStateOf("")};var saving by remember{mutableStateOf(false)};var error by remember{mutableStateOf("")};val scope=rememberCoroutineScope();AlertDialog(onDismissRequest={if(!saving)close()},title={Text("Transaksi Baru")},text={Column(Modifier.verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("POST /api/transaksi • Idempotency-Key otomatis",color=Muted);OutlinedTextField(product,{product=it},label={Text("Produk ID")},singleLine=true,modifier=Modifier.fillMaxWidth());OutlinedTextField(qty,{qty=it},label={Text("Qty")},singleLine=true,modifier=Modifier.fillMaxWidth());OutlinedTextField(method,{method=it},label={Text("Metode Bayar")},singleLine=true,modifier=Modifier.fillMaxWidth());OutlinedTextField(account,{account=it},label={Text("Akun Penerima")},singleLine=true,modifier=Modifier.fillMaxWidth());OutlinedTextField(customer,{customer=it},label={Text("Pelanggan ID")},singleLine=true,modifier=Modifier.fillMaxWidth());if(error.isNotBlank())Text(error,color=Scheme.error)}},confirmButton={Button(enabled=!saving,onClick={scope.launch{saving=true;val items=JSONArray();if(product.isNotBlank())items.put(JSONObject().put("produk_id",product).put("qty",qty.toLongOrNull()?:1));val body=JSONObject().put("items",items).put("metode_bayar",method).put("manual_entry",true);if(account.isNotBlank())body.put("akun_penerima",account);if(customer.isNotBlank())body.put("pelanggan_id",customer);runCatching{api.createTransaksi(body)}.onSuccess{close()}.onFailure{error=it.message?:"Gagal menyimpan transaksi"};saving=false}}){Text(if(saving)"Menyimpan…" else "Simpan")}},dismissButton={TextButton(enabled=!saving,onClick=close){Text("Batal")}})}

@Composable private fun SimpleJsonDialog(title:String,key1:String,key2:String,save:(JSONObject)->Unit){var v1 by remember{mutableStateOf("")};var v2 by remember{mutableStateOf("")};AlertDialog(onDismissRequest={},title={Text(title)},text={Column(verticalArrangement=Arrangement.spacedBy(8.dp)){OutlinedTextField(v1,{v1=it},label={Text(key1)},modifier=Modifier.fillMaxWidth());OutlinedTextField(v2,{v2=it},label={Text(key2)},modifier=Modifier.fillMaxWidth())}},confirmButton={Button(onClick={save(JSONObject().put(key1,v1).put(key2,v2.toLongOrNull()?:0L))}){Text("Simpan")}},dismissButton={TextButton(onClick={}){Text("Batal")}})}
